sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here
    var requestUser = request.pathParams.user_name;
    var requestNIQuery = request.queryParams.ni_query;

    var requestUserName = new GlideRecord('sys_user');
    requestUserName.get('user_name', requestUser);

    if (!requestUserName.user_name) {
        var apiError = new sn_ws_err.ServiceError();
        apiError.setStatus(542);
        apiError.setMessage("User not found");
        apiError.setDetail("No user record found for the user_name passed into the ni_info web service resource using the user_name path parameter.");
        response.setError(apiError);
        return;
    }

    var gr = new GlideAggregate('x_58872_needit_needit');
    gr.addAggregate('COUNT');
    gr.addQuery('u_requested_for', requestUserName.sys_id);
    gr.addEncodedQuery(requestNIQuery);
    gr.groupBy('u_request_type');
    gr.query();

    var result = [];
    var records = 0;
    var recordsCounts = 0;

    while (gr.next()) {
        records = gr.getAggregate('COUNT');
        var reqType = gr.u_request_type.getDisplayValue();
        result.push({
            "requestType": reqType,
            "Count": records
        });
        recordsCounts = parseInt(recordsCounts) + parseInt(records);
    }

    var body = {};
    body.totalUserRecords = recordsCounts;
    body.catcounts = result;
    body.user = {
        "User Name": requestUserName.user_name,
        "User Id": requestUserName.sys_id
    };

    response.setBody(body);

})(request, response);
